 public function update(Request $request,int $order,DeliveryChargeCalculator $calculator): RedirectResponse { $data=$this->validated($request);DB::transaction(function()use($data,$request,$order,$calculator){$record=DB::table('orders')->lockForUpdate()->find($order);abort_unless($record,404);abort_unless(in_array($record->status,['pending','confirmed','processing'],true),422,'This order can no longer be edited.');$oldItems=DB::table('order_items')->where('order_id',$order)->get();foreach($oldItems as $old){$restored=max(0,(int)$old->quantity-(int)($old->stock_shortage_quantity??0));if($restored<1)continue;$old->product_variant_id?ProductVariant::query()->whereKey($old->product_variant_id)->increment('stock_quantity',$restored):Product::query()->whereKey($old->product_id)->increment('stock_quantity',$restored);}$products=Product::query()->whereIn('id',collect($data['items'])->pluck('product_id'))->lockForUpdate()->get()->keyBy('id');$variants=ProductVariant::query()->whereIn('id',collect($data['items'])->pluck('variant_id')->filter())->lockForUpdate()->get()->keyBy('id');$settings=WebsiteSetting::firstOrCreate(['id'=>1]);$allow=(bool)($settings->allow_out_of_stock_orders??true);$subtotal=0.0;$short=false;$prepared=[];$deliveryLines=collect();foreach($data['items'] as $line){$product=$products->get($line['product_id']);$variant=filled($line['variant_id']??null)?$variants->get($line['variant_id']):null;abort_unless($product&&in_array($product->status,['Published','Active'],true),422,'One or more products are unavailable.');abort_if($variant&&(int)$variant->product_id!==(int)$product->id,422,'The selected variant does not belong to its product.');$stock=(int)($variant?->stock_quantity??$product->stock_quantity);abort_if(!$allow&&$stock<$line['quantity'],422,$product->title.' does not have enough stock.');$price=round((float)$line['unit_price'],2);$lineTotal=$price*$line['quantity'];$subtotal+=$lineTotal;$shortage=max(0,$line['quantity']-$stock);$short=$short||$shortage>