seif(!$line['variant']&&$line['stock']>0)$line['product']->decrement('stock_quantity',min($line['stock'],$line['quantity']));}});return to_route('orders.show',$order)->with('success','Order updated successfully.'); }
 public function destroy(int $order): RedirectResponse { DB::transaction(function()use($order){$record=DB::table('orders')->lockForUpdate()->find($order);abort_unless($record,404);abort_unless($record->status==='pending'&&$record->payment_status!=='paid',422,'Only an unpaid pending order can be deleted.');foreach(DB::table('order_items')->where('order_id',$order)->get() as $item){$restored=max(0,(int)$item->quantity-(int)($item->stock_shortage_quantity??0));if($restored<1)continue;$item->product_variant_id?ProductVariant::query()->whereKey($item->product_variant_id)->increment('stock_quantity',$restored):Product::query()->whereKey($item->product_id)->increment('stock_quantity',$restored);}DB::table('orders')->where('id',$order)->delete();});return to_route('orders.index')->with('success','Order deleted successfully.'); }
 private function validated(Request $request): array { $data=$request->validate(['source'=>['required',Rule::in(['phone','whatsapp','manual'])],'user_id'=>['nullable','integer','exists:users,id'],'customer_name'=>['required','string','max:120'],'phone'=>['required','string','max:30'],'email'=>['nullable','email','max:255'],'address'=>['required','string','max:1000'],'city'=>['required','string','max:120'],'delivery_zone'=>['required',Rule::in(['inside_dhaka','outside_dhaka'])],'note'=>['nullable','string','max:2000'],'payment_method'=>['required',Rule::in(['cod'])],'payment_status'=>['required',Rule::in(['pending','paid'])],'discount'=>['nullable','numeric','min:0'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id'],'items.*.variant_id'=>['nullable','integer','exists:product_variants,id'],'items.*.quantity'=>['required','integer','min:1','max:999'],'items.*.unit_price'=>['required','numeric','min:0']]);if(filled($data['user_id']??null))abort_if(User::query()->whereKey($data['user_id'])->where('is_admin',true)->exists(),422,'An admin account cannot be selected as a customer.');return $data; }
